 Kártya, Apple Pay, Google Pay támogatás

Fontos megjegyzés: A Flash alapvetően Bitcoin Lightning fizetéseket kezel[1][2]. Ha a vásárlók kártyával, Apple Payjel vagy Google Payjel szeretnének fizetni HUFban, akkor a Flash nem a legjobb választás, mert ő csak kripto fizetéseket fogad el közvetlenül[2].

A kártyás/Apple Pay/Google Pay fizetéshez más szolgáltatást kell használnod, például:
 NOWPayments: Támogatja a kártyás fizetést HUFban, automatikusan konvertál kriptóra[9][3]
 CoinGate: Szintén támogatja a fiat kártyás fizetést és automatikus kripto konverziót[3][10]

 Összefoglalás

A Flash remek választás, ha a vásárlók Bitcoinnal fizetnek, de ha kártyás/Apple Pay/Google Pay fizetést is szeretnél HUFban, akkor a NOWPayments vagy CoinGate jobb megoldás, mert azok támogatják a fiatkripto automatikus konverziót[9][3][10].

Rendben, itt egy teljes Python Flask backend Flash payment gatewayjel! A Flash REST APIját fogjuk használni.

 Python Flask backend Flash integrációval

 1. Projekt setup

bash
pip install flask requests python-dotenv


Hozz létre egy .env fájlt:

FLASH_API_KEY=your_flash_api_key_here
FLASK_SECRET_KEY=your_random_secret_key
BITCOIN_WALLET_ADDRESS=your_bitcoin_lightning_address


 2. Backend kód (app.py)

python
from flask import Flask, request, jsonify, render_template
import requests
import os
import time
from dotenv import load_dotenv

load_dotenv()

app = Flask(__name__)
app.config['SECRET_KEY'] = os.getenv('FLASK_SECRET_KEY')

# Flash API beállítások
FLASH_API_URL = "https://api.paywithflash.com/v1"
FLASH_API_KEY = os.getenv('FLASH_API_KEY')
BITCOIN_WALLET = os.getenv('BITCOIN_WALLET_ADDRESS')

def get_huf_to_btc_rate():
    """
    HUF -> BTC átváltási árfolyam lekérése
    """
    try:
        # Coinbase vagy más exchange API használata
        response = requests.get('https://api.coinbase.com/v2/exchange-rates?currency=BTC')
        data = response.json()
        huf_rate = float(data['data']['rates']['HUF'])
        btc_per_huf = 1 / huf_rate
        return btc_per_huf
    except Exception as e:
        print(f"Árfolyam lekérés hiba: {e}")
        # Backup árfolyam (1 BTC = ~36,000,000 HUF)
        return 1 / 36000000

@app.route('/')
def index():
    """
    Frontend oldal renderelése
    """
    return render_template('index.html')

@app.route('/api/create-payment', methods=['POST'])
def create_payment():
    """
    Flash fizetés létrehozása
    """
    try:
        data = request.get_json()
        amount_huf = float(data.get('amount', 0))
        description = data.get('description', 'Zsebibaba Időpontfoglalás')
        booking_date = data.get('booking_date', '')
        booking_time = data.get('booking_time', '')

        if amount_huf <= 0:
            return jsonify({'success': False, 'error': 'Érvénytelen összeg'}), 400

        # HUF -> BTC konverzió
        btc_rate = get_huf_to_btc_rate()
        amount_btc = amount_huf * btc_rate

        # Satoshi-ba konvertálás (1 BTC = 100,000,000 satoshi)
        amount_satoshi = int(amount_btc * 100000000)

        # Flash payment létrehozása
        payment_data = {
            'amount': amount_satoshi,
            'currency': 'sat',  # Satoshi
            'description': f"{description} - {booking_date} {booking_time}",
            'webhook_url': f"{request.host_url}api/webhook",
            'success_url': f"{request.host_url}success",
            'cancel_url': f"{request.host_url}cancel",
            'metadata': {
                'order_id': f'order_{int(time.time())}',
                'booking_date': booking_date,
                'booking_time': booking_time
            }
        }

        headers = {
            'Authorization': f'Bearer {FLASH_API_KEY}',
            'Content-Type': 'application/json'
        }

        response = requests.post(
            f'{FLASH_API_URL}/payment',
            json=payment_data,
            headers=headers
        )

        if response.status_code == 200 or response.status_code == 201:
            payment_response = response.json()
            return jsonify({
                'success': True,
                'payment_id': payment_response.get('id'),
                'payment_url': payment_response.get('checkout_url'),
                'invoice': payment_response.get('invoice'),
                'amount_huf': amount_huf,
                'amount_btc': amount_btc
            })
        else:
            return jsonify({
                'success': False,
                'error': 'Flash API hiba',
                'details': response.text
            }), 400

    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/payment-status/<payment_id>', methods=['GET'])
def check_payment_status(payment_id):
    """
    Fizetés státuszának ellenőrzése
    """
    try:
        headers = {
            'Authorization': f'Bearer {FLASH_API_KEY}',
            'Content-Type': 'application/json'
        }

        response = requests.get(
            f'{FLASH_API_URL}/payment/{payment_id}',
            headers=headers
        )

        if response.status_code == 200:
            payment_data = response.json()
            return jsonify({
                'success': True,
                'status': payment_data.get('status'),
                'paid': payment_data.get('paid', False),
                'amount': payment_data.get('amount'),
                'created_at': payment_data.get('created_at')
            })
        else:
            return jsonify({
                'success': False,
                'error': 'Nem található a fizetés'
            }), 404

    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/webhook', methods=['POST'])
def webhook():
    """
    Flash webhook - automatikus értesítés sikeres fizetésről
    """
    try:
        data = request.get_json()

        # Flash webhook signature ellenőrzés (opcionális de ajánlott)
        # signature = request.headers.get('X-Flash-Signature')

        payment_id = data.get('id')
        status = data.get('status')
        paid = data.get('paid', False)
        metadata = data.get('metadata', {})

        if paid and status == 'completed':
            # Sikeres fizetés
            order_id = metadata.get('order_id')
            booking_date = metadata.get('booking_date')
            booking_time = metadata.get('booking_time')

            print(f"✅ Sikeres fizetés!")
            print(f"Payment ID: {payment_id}")
            print(f"Order ID: {order_id}")
            print(f"Időpont: {booking_date} {booking_time}")

            # Itt:
            # - Mentsd el az adatbázisba a foglalást
            # - Küldj email-t a vásárlónak
            # - Küldj értesítést magadnak

        return jsonify({'success': True}), 200

    except Exception as e:
        print(f"Webhook hiba: {e}")
        return jsonify({'success': False, 'error': str(e)}), 400

@app.route('/success')
def success():
    """
    Sikeres fizetés oldal
    """
    return "<h1>Sikeres fizetés!</h1><p>Köszönjük a foglalást.</p>"

@app.route('/cancel')
def cancel():
    """
    Megszakított fizetés oldal
    """
    return "<h1>Fizetés megszakítva</h1><p>A foglalás nem jött létre.</p>"

if __name__ == '__main__':
    app.run(debug=True, port=5000)


