PAYGATE_API_KEY = os.getenv('PAYGATE_API_KEY')
PAYGATE_API_URL = "https://api.paygate.to/v1"

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/api/create-payment', methods=['POST'])
def create_payment():
    """
    PayGate.to payment létrehozása
    """
    try:
        data = request.get_json()
        amount_huf = float(data.get('amount', 0))
        description = data.get('description', 'Zsebibaba Időpontfoglalás')
        booking_date = data.get('booking_date', '')
        booking_time = data.get('booking_time', '')

        # PayGate.to payment request
        payment_data = {
            'merchant_id': PAYGATE_MERCHANT_ID,
            'amount': amount_huf,
            'currency': 'HUF',
            'payout_currency': 'BTC',  # vagy 'USDT', 'USDC'
            'description': f"{description} - {booking_date} {booking_time}",
            'order_id': f'order_{int(time.time())}',
            'callback_url': f'{request.host_url}api/webhook',
            'success_url': f'{request.host_url}success',
            'cancel_url': f'{request.host_url}cancel',
            'payment_methods': ['card', 'apple_pay', 'google_pay']
        }

        # API kulcs aláírás
        signature = generate_signature(payment_data, PAYGATE_API_KEY)
        payment_data['signature'] = signature

        headers = {
            'Content-Type': 'application/json',
            'X-API-Key': PAYGATE_API_KEY
        }

        response = requests.post(
            f'{PAYGATE_API_URL}/payments',
            json=payment_data,
            headers=headers
        )

        if response.status_code in [200, 201]:
            result = response.json()
            return jsonify({
                'success': True,
                'payment_id': result.get('payment_id'),
                'payment_url': result.get('payment_url'),
                # Vagy embedded widget token
                'widget_token': result.get('widget_token')
            })
        else:
            return jsonify({
                'success': False,
                'error': response.text
            }), 400

    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

def generate_signature(data, api_key):
    """
    PayGate.to aláírás generálás
    """
    # Rendezd az adatokat és készíts hash-t
    sorted_data = ''.join([str(v) for k, v in sorted(data.items()) if k != 'signature'])
    signature_string = sorted_data + api_key
    return hashlib.sha256(signature_string.encode()).hexdigest()

@app.route('/api/webhook', methods=['POST'])
def webhook():
    """
